insert into public.triage_versions (care_line, version, definition, published_at) values ('cabelo', 1, '{"care_line":"cabelo","title":"Triagem — Cabelo","intro":"Estas respostas vão para o médico antes da consulta. Leva cerca de 5 minutos.","questions":[{"id":"sexo","type":"single","label":"Qual é o seu sexo ao nascer?","help":"Algumas condições e cuidados mudam conforme o sexo biológico.","required":true,"options":[{"value":"F","label":"Feminino"},{"value":"M","label":"Masculino"}]},{"id":"gestacao","type":"single","label":"Você está grávida, amamentando ou tentando engravidar?","required":true,"showIf":{"q":"sexo","op":"eq","value":"F"},"options":[{"value":"nao","label":"Não"},{"value":"gravida","label":"Estou grávida"},{"value":"amamentando","label":"Estou amamentando"},{"value":"tentando","label":"Estou tentando engravidar"}],"alert":{"when":{"q":"gestacao","op":"in","value":["gravida","amamentando","tentando"]},"code":"gestacao","label":"Gestação, amamentação ou tentativa de engravidar"}},{"id":"peso","type":"number","label":"Qual é o seu peso?","unit":"kg","min":30,"max":300,"required":true},{"id":"altura","type":"number","label":"Qual é a sua altura?","unit":"cm","min":120,"max":230,"required":true},{"id":"doencas","type":"multi","label":"Você tem ou já teve alguma destas condições?","required":true,"exclusiveValue":"nenhuma","options":[{"value":"pressao_alta","label":"Pressão alta"},{"value":"coracao","label":"Doença do coração"},{"value":"figado","label":"Doença do fígado"},{"value":"rins","label":"Doença dos rins"},{"value":"diabetes","label":"Diabetes"},{"value":"tireoide","label":"Problema de tireoide"},{"value":"cancer","label":"Câncer"},{"value":"nenhuma","label":"Nenhuma"}],"alert":{"when":{"q":"doencas","op":"includesAny","value":["coracao","figado","rins","cancer"]},"code":"comorbidade","label":"Doença de coração, fígado, rins ou câncer"}},{"id":"uso_atual","type":"text","label":"Você usa algum remédio, vitamina ou suplemento hoje? Quais?","help":"Se não usa nada, escreva \"nenhum\".","maxLength":600,"required":true},{"id":"alergias","type":"text","label":"Você tem alergia a algum remédio ou substância? Qual?","help":"Se não tem, escreva \"nenhuma\".","maxLength":400,"required":true},{"id":"cirurgia_recente","type":"yesno","label":"Você fez cirurgia ou ficou internado nos últimos 6 meses?","required":true,"options":[{"value":"sim","label":"Sim"},{"value":"nao","label":"Não"}],"alert":{"when":{"q":"cirurgia_recente","op":"eq","value":"sim"},"code":"cirurgia_recente","label":"Cirurgia ou internação nos últimos 6 meses"}},{"id":"urgencia","type":"multi","label":"Agora, neste momento, você sente algum destes sinais?","required":true,"exclusiveValue":"nenhum","options":[{"value":"dor_peito","label":"Dor ou aperto no peito"},{"value":"falta_ar","label":"Falta de ar"},{"value":"desmaio","label":"Desmaio ou quase desmaio"},{"value":"fraqueza_lado","label":"Fraqueza ou formigamento de um lado do corpo"},{"value":"sangramento","label":"Sangramento que não para"},{"value":"nenhum","label":"Nenhum destes"}],"block":{"when":{"q":"urgencia","op":"excludesAll","value":["nenhum"]},"kind":"emergency"}},{"id":"cabelo_tempo","type":"single","label":"Há quanto tempo você percebe a queda?","required":true,"options":[{"value":"menos_3m","label":"Menos de 3 meses"},{"value":"3_12m","label":"De 3 a 12 meses"},{"value":"mais_1a","label":"Mais de 1 ano"}]},{"id":"cabelo_onde","type":"multi","label":"Onde você percebe a queda?","required":true,"options":[{"value":"entradas","label":"Entradas"},{"value":"topo","label":"Topo da cabeça"},{"value":"difusa","label":"Em toda a cabeça"},{"value":"falhas_redondas","label":"Falhas redondas"}],"alert":{"when":{"q":"cabelo_onde","op":"includesAny","value":["falhas_redondas"]},"code":"falhas_redondas","label":"Falhas redondas (avaliar necessidade de exame presencial)"}},{"id":"cabelo_familia","type":"yesno","label":"Alguém da sua família tem calvície?","required":true,"options":[{"value":"sim","label":"Sim"},{"value":"nao","label":"Não"},{"value":"nao_sei","label":"Não sei"}]},{"id":"cabelo_couro","type":"multi","label":"Você tem algum destes sinais no couro cabeludo?","required":true,"exclusiveValue":"nenhum","options":[{"value":"coceira","label":"Coceira"},{"value":"descamacao","label":"Descamação"},{"value":"feridas","label":"Feridas"},{"value":"nenhum","label":"Nenhum"}],"alert":{"when":{"q":"cabelo_couro","op":"includesAny","value":["feridas"]},"code":"feridas_couro","label":"Feridas no couro cabeludo"}},{"id":"cabelo_tentativas","type":"text","label":"Você já tratou a queda antes? Com o quê?","help":"Se nunca tratou, escreva \"nunca\".","maxLength":500,"required":true},{"id":"cabelo_fotos","type":"photos","label":"Quer enviar fotos do couro cabeludo? (opcional)","help":"Frente, topo e lateral, com boa luz. Só o médico vê.","maxFiles":3,"required":false},{"id":"relato","type":"text","label":"Conte com suas palavras o que está acontecendo e o que você espera da consulta.","maxLength":1000,"required":true}]}'::jsonb, now()) on conflict (care_line, version) do nothing;
